1	/**
2	 * The offline-faithful rebuild of the `angular-tiny-translator-v0-12-0`
3	 * migrated lane.
4	 *
5	 * u21 read the emitted `dist-13/index.html` and found an `@font-face` rule that
6	 * exists in no input: the Angular 16 browser builder's font inliner had gone to
7	 * `fonts.googleapis.com` during the build and pasted the answer into the
8	 * document. That is a build-time third-party request nobody declared, and it
9	 * makes the emitted bytes a property of what a font host served on the build
10	 * day. The capability that turns it off is landed in `@versionless/angular`;
11	 * this driver applies it to the staged workspace and rebuilds the lane.
12	 *
13	 * The driver measures rather than asserts. Every build it runs — including the
14	 * control it runs BEFORE applying the capability — runs under an in-process
15	 * egress guard that refuses and records any connection to a non-loopback
16	 * address. The control is the point: a build of the workspace as u19k left it
17	 * is expected to reach for the font host and to fail when it cannot, which is
18	 * what makes the green build afterwards evidence of something. A control that
19	 * came back green would mean the fetch was being served from somewhere and this
20	 * whole round would be measuring nothing.
21	 *
22	 * Nothing about fonts, hosts or this application is decided here. Which targets
23	 * carry the option and what value it takes is read out of the capability, whose
24	 * only inputs are the builder name and the shape of the declared `optimization`
25	 * value.
26	 */
27	
28	import { readFile, rm, writeFile } from 'node:fs/promises';
29	import { spawn } from 'node:child_process';
30	import * as path from 'pathe';
31	import {
32		builderInlinesFonts,
33		fontInliningDifference,
34		fontInliningDisabled,
35		ANGULAR_16_BROWSER_CELL,
36	} from '../../../frameworks/angular/src/index.ts';
37	import { APPLIED_TREE, STAGE_DIRECTORY } from './angular-tiny-translator-apply-run.ts';
38	
39	export const UNIT = 'lrapr-t006/u22-tiny-translator-offline-rebuild';
40	/** The output roots this round emits: the canonical one and its repeat. */
41	export const CANONICAL_ROOT = 'dist-15';
42	export const REPEATED_ROOT = 'dist-16';
43	/** The control build, run before the capability is applied and expected red. */
44	export const CONTROL_ROOT = 'dist-offline-control';
45	/** The Angular 16 cell's Node runtime, already materialised in this checkout. */
46	const NODE_BIN = path.join(
47		path.resolve(import.meta.dirname, '../../../..'),
48		'.versionless/cache/angular-jira-clone-runtime/node-v16.20.2-darwin-arm64/bin',
49	);
50	
51	/**
52	 * The egress guard, written beside the stage tree and preloaded into every
53	 * build this driver runs.
54	 *
55	 * It patches the two places a Node process can leave the machine from — the
56	 * socket connect that every `http`, `https` and `tls` client ends up at, and
57	 * the DNS lookup that precedes it — records every attempt with its host and
58	 * port to a JSON-lines file, and then refuses the ones that are not loopback.
59	 * Recording before refusing is what makes the file evidence: a build that made
60	 * no attempt and a build whose attempt was refused are different facts, and a
61	 * guard that only refused could not tell them apart.
62	 *
63	 * The guard is process-scoped, exactly like the Witness locality claim. It
64	 * establishes what THIS process attempted; it does not establish that the
65	 * machine was offline.
66	 */
67	export const EGRESS_GUARD_SOURCE = `'use strict';
68	const fs = require('node:fs');
69	const net = require('node:net');
70	const dns = require('node:dns');
71	const log = process.env.VERSIONLESS_EGRESS_LOG;
72	const LOOPBACK = new Set(['127.0.0.1', '::1', 'localhost', '0.0.0.0', '', undefined, null]);
73	const record = (kind, host, port) => {
74	  fs.appendFileSync(log, JSON.stringify({ kind, host: String(host), port: port ?? null }) + '\\n');
75	};
76	const local = (host) => LOOPBACK.has(host) || String(host).startsWith('127.');
77	const connect = net.Socket.prototype.connect;
78	net.Socket.prototype.connect = function (...args) {
79	  const first = args[0];
80	  const options = typeof first === 'object' && first !== null ? first : { port: first, host: args[1] };
81	  const host = options.host ?? options.path ?? 'localhost';
82	  if (options.path === undefined && !local(host)) {
83	    record('socket-connect', host, options.port);
84	    throw new Error('VERSIONLESS_EGRESS_REFUSED ' + String(host) + ':' + String(options.port));
85	  }
86	  return connect.apply(this, args);
87	};
88	const lookup = dns.lookup;
89	dns.lookup = function (hostname, ...rest) {
90	  if (!local(hostname)) {
91	    record('dns-lookup', hostname, null);
92	    const callback = rest[rest.length - 1];
93	    const error = new Error('VERSIONLESS_EGRESS_REFUSED ' + String(hostname));
94	    if (typeof callback === 'function') { callback(error); return; }
95	    throw error;
96	  }
97	  return lookup.call(dns, hostname, ...rest);
98	};
99	`;
100	
101	export type EgressAttempt = Readonly<{ kind: string; host: string; port: number | null }>;
102	
103	export type BuildReading = Readonly<{
104		name: string;
105		command: string;
106		outputRoot: string;
107		exitStatus: number;
108		bundleLines: number;
109		egressAttempts: readonly EgressAttempt[];
110		failure: string | null;
111	}>;
112	
113	/** Every non-loopback attempt one guarded build made, in the order it made them. */
114	async function readEgress(logFile: string): Promise<readonly EgressAttempt[]> {
115		const text = await readFile(logFile, 'utf8').catch(() => '');
116		return Object.freeze(
117			text
118				.split('\n')
119				.filter((line) => line.length > 0)
120				.map((line) => JSON.parse(line) as EgressAttempt),
121		);
122	}
123	
124	/** The one line of a build log that says why an inlining build died. */
125	function failureLine(log: string): string | null {
126		const line = log.split('\n').find((entry) => entry.includes('Inlining of fonts failed'));
127		return line === undefined ? null : line.trim();
128	}
129	
130	/**
131	 * Run one production build under the egress guard, into a cleaned output root.
132	 *
133	 * The output root is removed first so a build that emits nothing cannot be read
134	 * as a build that emitted what the previous one left behind, and the guard log
135	 * is removed with it so each reading belongs to exactly one build.
136	 */
137	export async function guardedBuild(name: string, outputRoot: string): Promise<BuildReading> {
138		const guard = path.join(STAGE_DIRECTORY, 'egress-guard.cjs');
139		const egressLog = path.join(STAGE_DIRECTORY, `${name}.egress.jsonl`);
140		await writeFile(guard, EGRESS_GUARD_SOURCE);
141		await rm(egressLog, { force: true });
142		await writeFile(egressLog, '');
143		await rm(path.join(STAGE_DIRECTORY, outputRoot), { recursive: true, force: true });
144		const command = `npx ng build --configuration production --output-path ../${outputRoot}`;
145		const { code, stdout, stderr } = await new Promise<{
146			code: number;
147			stdout: string;
148			stderr: string;
149		}>((settle, fail) => {
150			let out = '';
151			let err = '';
152			const child = spawn(
153				'npx',
154				['ng', 'build', '--configuration', 'production', '--output-path', `../${outputRoot}`],
155				{
156					cwd: APPLIED_TREE,
157					env: {
158						...process.env,
159						PATH: `${NODE_BIN}:${process.env['PATH'] ?? ''}`,
160						NODE_OPTIONS: `--require ${guard}`,
161						VERSIONLESS_EGRESS_LOG: egressLog,
162						VERSIONLESS_NETWORK_MODE: 'offline',
163						NPM_CONFIG_OFFLINE: 'true',
164						NG_CLI_ANALYTICS: 'false',
165					},
166				},
167			);
168			child.stdout.on('data', (chunk: Buffer) => (out += chunk.toString('utf8')));
169			child.stderr.on('data', (chunk: Buffer) => (err += chunk.toString('utf8')));
170			child.on('error', fail);
171			child.on('close', (status) => settle({ code: status ?? -1, stdout: out, stderr: err }));
172		});
173		await writeFile(path.join(STAGE_DIRECTORY, `${name}.exit`), `${String(code)}\n`);
174		await writeFile(path.join(STAGE_DIRECTORY, `${name}.stdout.log`), stdout);
175		await writeFile(path.join(STAGE_DIRECTORY, `${name}.stderr.log`), stderr);
176		return Object.freeze({
177			name,
178			command,
179			outputRoot,
180			exitStatus: code,
181			bundleLines: stdout.split('\n').filter((line) => line.includes('.js')).length,
182			egressAttempts: await readEgress(egressLog),
183			failure: failureLine(`${stdout}\n${stderr}`),
184		});
185	}
186	
187	/**
188	 * One site the capability rewrote. `from` is null when the site declared no
189	 * `optimization` at all, which is a different fact from declaring `null`: an
190	 * absent option is the schema's `true`, and it is the reason the base options
191	 * are written rather than left alone.
192	 */
193	export type FontInliningSite = Readonly<{ at: string; from: string | null; to: string }>;
194	
195	export type WorkspaceApplication = Readonly<{
196		workspace: string;
197		targetsRead: number;
198		inliningTargets: number;
199		sites: readonly FontInliningSite[];
200		declaredDifferences: readonly string[];
201		changed: boolean;
202	}>;
203	
204	type Json = Readonly<Record<string, unknown>>;
205	
206	const objectAt = (value: unknown): Json | null =>
207		typeof value === 'object' && value !== null && !Array.isArray(value)
208			? (value as Json)
209			: null;
210	
211	/**
212	 * Apply the font-inlining-disable capability to the staged workspace, exactly
213	 * as the landed workspace migration applies it.
214	 *
215	 * Base options are written even when they declare no `optimization`, because an
216	 * absent option is the schema's `true` and therefore inlines; a named
217	 * configuration is only rewritten when it declares the option itself, because
218	 * writing one into a configuration that inherits is a change to what that
219	 * configuration means. Both rules are the capability's, not this driver's.
220	 */
221	export async function applyFontInliningDisable(): Promise<WorkspaceApplication> {
222		const file = path.join(APPLIED_TREE, 'angular.json');
223		const source = await readFile(file, 'utf8');
224		const workspace = JSON.parse(source) as Json;
225		const sites: FontInliningSite[] = [];
226		const declaredDifferences: string[] = [];
227		let targetsRead = 0;
228		let inliningTargets = 0;
229		const projects = objectAt(workspace['projects']) ?? {};
230		for (const [projectName, projectValue] of Object.entries(projects)) {
231			const architect = objectAt(objectAt(projectValue)?.['architect']);
232			if (architect === null) continue;
233			for (const [targetName, targetValue] of Object.entries(architect)) {
234				const target = objectAt(targetValue);
235				if (target === null) continue;
236				targetsRead += 1;
237				const builder = target['builder'];
238				if (typeof builder !== 'string' || !builderInlinesFonts(builder)) continue;
239				inliningTargets += 1;
240				const prefix = `projects.${projectName}.architect.${targetName}`;
241				const options = objectAt(target['options']);
242				if (options !== null) {
243					const declared = options['optimization'];
244					const disabled = fontInliningDisabled(declared);
245					if (disabled !== null) {
246						(options as Record<string, unknown>)['optimization'] = disabled;
247						sites.push({
248							at: `${prefix}.options.optimization`,
249							from: declared === undefined ? null : JSON.stringify(declared),
250							to: JSON.stringify(disabled),
251						});
252						declaredDifferences.push(
253							fontInliningDifference(
254								`${prefix}.options.optimization`,
255								ANGULAR_16_BROWSER_CELL,
256							),
257						);
258					}
259				}
260				const configurations = objectAt(target['configurations']);
261				if (configurations === null) continue;
262				for (const [name, value] of Object.entries(configurations)) {
263					const configuration = objectAt(value);
264					if (configuration === null || !('optimization' in configuration)) continue;
265					const declared = configuration['optimization'];
266					const disabled = fontInliningDisabled(declared);
267					if (disabled === null) continue;
268					(configuration as Record<string, unknown>)['optimization'] = disabled;
269					sites.push({
270						at: `${prefix}.configurations.${name}.optimization`,
271						from: JSON.stringify(declared),
272						to: JSON.stringify(disabled),
273					});
274					declaredDifferences.push(
275						fontInliningDifference(
276							`${prefix}.configurations.${name}.optimization`,
277							ANGULAR_16_BROWSER_CELL,
278						),
279					);
280				}
281			}
282		}
283		const next = `${JSON.stringify(workspace, null, 2)}\n`;
284		const changed = next !== source;
285		if (changed) await writeFile(file, next);
286		return Object.freeze({
287			workspace: 'angular.json',
288			targetsRead,
289			inliningTargets,
290			sites: Object.freeze(sites),
291			declaredDifferences: Object.freeze(declaredDifferences),
292			changed,
293		});
294	}
295	
296	export type FontRound = Readonly<{
297		control: BuildReading;
298		application: WorkspaceApplication;
299		builds: readonly BuildReading[];
300	}>;
301	
302	/**
303	 * The whole round, in the only order that makes it evidence: control first,
304	 * against the workspace as u19k left it, then the capability, then the two
305	 * builds the lane publishes.
306	 */
307	export async function runFontRound(): Promise<FontRound> {
308		const control = await guardedBuild('build-offline-control', CONTROL_ROOT);
309		const application = await applyFontInliningDisable();
310		const first = await guardedBuild('build-15', CANONICAL_ROOT);
311		const second = await guardedBuild('build-16', REPEATED_ROOT);
312		return Object.freeze({ control, application, builds: Object.freeze([first, second]) });
313	}
314	
315	export async function main(): Promise<void> {
316		const round = await runFontRound();
317		await writeFile(
318			path.join(STAGE_DIRECTORY, 'font-round.json'),
319			`${JSON.stringify(round, null, '\t')}\n`,
320		);
321		process.stdout.write(
322			`control exit ${String(round.control.exitStatus)}, ` +
323				`${String(round.control.egressAttempts.length)} egress attempt(s)\n`,
324		);
325		for (const site of round.application.sites) process.stdout.write(`applied: ${site.at}\n`);
326		for (const build of round.builds)
327			process.stdout.write(
328				`${build.name} exit ${String(build.exitStatus)}, ` +
329					`${String(build.egressAttempts.length)} egress attempt(s)\n`,
330			);
331	}
332	
333	if (process.argv[1]?.endsWith('angular-tiny-translator-u22-font-run.ts'))
334		main().catch((error: unknown) => {
335			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
336			process.exitCode = 1;
337		});
