import { readFile, rm, writeFile } from 'node:fs/promises';
import { spawn } from 'node:child_process';
import * as path from 'pathe';
import {
	builderInlinesFonts,
	fontInliningDifference,
	fontInliningDisabled,
	ANGULAR_16_BROWSER_CELL,
