/**
 * The record of the offline-faithful rebuild: the migrated super-productivity
 * lane with the Angular 16 font inliner turned off.
 *
 * u21 read `app/dist/index.html` — the document u18j published — and found
 * forty-five `@font-face` rules that exist in no input, which is the body of the
 * Roboto stylesheet the builder fetched from `fonts.googleapis.com` while the
 * build was running. u21 established that from the document alone and said so:
 * it observed no build and captured no traffic. This round observes the build.
 *
 * Every number here is read at the moment the record is written: three build
 * logs, three egress logs, three emitted inventories — the two this round
 * produced and the superseded one, which is still on disk — the source and
 * emitted documents, the emitted runtime chunk and the emitted service-worker
 * manifest. The control build is part of the evidence rather than a rehearsal:
 * it is the same workspace u18j built, run under the same guard, and it goes red
 * on the fetch. A green control would have meant the guard was measuring
 * nothing.
 *
 * No witness work is done here and none is claimed. The deliverable is the
 * corrected lane and the record of it; the browser proof for this vertical
 * resumes against these bytes.
 */

import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { charNotIn, createRegExp, exactly, global as globalFlag, oneOrMore } from 'magic-regexp';
import * as path from 'pathe';
import { canonical, sha256 } from './angular-factoriolab-migration-run.ts';
import {
	emissionPointOf,
	inventoryOf,
	sealRecord,
	verifySealedRecord,
	type DistEntry,
	type SealedRecord,
} from './angular-factoriolab-build-lanes-run.ts';
import { CONSENT, EVIDENCE_DIRECTORY } from './angular-super-productivity-lanes-run.ts';
import { APPLIED_TREE, STAGE_DIRECTORY } from './angular-super-productivity-apply-run.ts';
import {
	CANONICAL_ROOT,
	REPEATED_ROOT,
	UNIT,
	type FontRound,
} from './angular-super-productivity-u23-font-run.ts';

export const FONT_LANE_FILE = 'u23-offline-font-lane.json';
/** The output root u18j published, kept on disk and read here as the superseded lane. */
export const SUPERSEDED_ROOT = 'app/dist';
/** The record this round supersedes, and the u21 reading it answers. */
export const SUPERSEDED_RECORD = 'u18j-worker-chunks-parity.json';
export const LOCALITY_FINDING = Object.freeze({
	record: 'evidence/runs/angular-super-productivity-v2-13-15/u21-font-inline-locality.json',
	digest: '7f7dbf94127e57ca79029a6c93a74ffd61f2ec1347e4ce3bf25b55bdbee5ff2a',
});

const LINK_HREF = createRegExp(
	exactly('<link')
		.and(oneOrMore(charNotIn('>')))
		.and('href="')
		.and(oneOrMore(charNotIn('"')).groupedAs('href'))
		.and('"'),
	[globalFlag],
);

/** Every `<link>` href in a document, in document order. */
export function linkHrefs(html: string): readonly string[] {
	return Object.freeze(
		[...html.matchAll(LINK_HREF)].map((match) => match.groups['href'] as string),
	);
}

/** How many `@font-face` rules a document carries in its own bytes. */
export function fontFaceRules(html: string): number {
	return html.split('@font-face').length - 1;
}

/** An inventory as a path → digest map, for set comparisons. */
function digestsOf(inventory: readonly DistEntry[]): ReadonlyMap<string, string> {
	return new Map(inventory.map((entry) => [entry.path, entry.sha256]));
}

/**
 * The reading that says whether the difference between two emitted chunks is
 * this cell's recorded Sass nondeterminism rather than something this round did.
 *
 * The era baseline chased that instability to one line — a `@keyframes bang`
 * whose box-shadow list is generated by unseeded Sass `random()` — and the only
 * honest way to attribute a moved content hash to it is to walk to the first
 * byte where the two chunks disagree and read what is written there.
 */
export function firstDifference(
	left: string,
	right: string,
): Readonly<{ offset: number; leftExcerpt: string; rightExcerpt: string; insideBangKeyframes: boolean }> | null {
	const shortest = Math.min(left.length, right.length);
	let offset = 0;
	while (offset < shortest && left[offset] === right[offset]) offset += 1;
	if (offset === shortest && left.length === right.length) return null;
	const window = 96;
	const preceding = left.slice(Math.max(0, offset - window), offset);
	return Object.freeze({
		offset,
		leftExcerpt: left.slice(offset, offset + window),
		rightExcerpt: right.slice(offset, offset + window),
		insideBangKeyframes: preceding.includes('_bang{') && preceding.includes('box-shadow'),
	});
}

export async function buildFontLaneRecord(): Promise<SealedRecord> {
	const round = JSON.parse(
		await readFile(path.join(STAGE_DIRECTORY, 'u23-font-round.json'), 'utf8'),
	) as FontRound;
	const first = await inventoryOf(path.join(STAGE_DIRECTORY, CANONICAL_ROOT));
	const second = await inventoryOf(path.join(STAGE_DIRECTORY, REPEATED_ROOT));
	const superseded = await inventoryOf(path.join(STAGE_DIRECTORY, SUPERSEDED_ROOT));
	const identical = canonical(first) === canonical(second);
	const firstDigests = digestsOf(first);
	const secondDigests = digestsOf(second);
	const supersededDigests = digestsOf(superseded);
	const differingAcrossRuns = first
		.filter((entry) => secondDigests.get(entry.path) !== entry.sha256)
		.map((entry) => entry.path);
	const namesUnchanged = [...firstDigests.keys()].filter((name) => supersededDigests.has(name));
	const changedAgainstSuperseded = namesUnchanged.filter(
		(name) => firstDigests.get(name) !== supersededDigests.get(name),
	);
	const logical = (inventory: readonly DistEntry[]): readonly string[] =>
		Object.freeze([...new Set(inventory.map((entry) => emissionPointOf(entry.path)))].sort());
	const logicalNow = logical(first);
	const logicalThen = logical(superseded);
	const censusHolds =
		first.length === superseded.length &&
		canonical(logicalNow) === canonical(logicalThen);

	const sourceIndex = await readFile(path.join(APPLIED_TREE, 'src/index.html'), 'utf8');
	const emittedIndex = await readFile(
		path.join(STAGE_DIRECTORY, CANONICAL_ROOT, 'index.html'),
		'utf8',
	);
	const supersededIndex = await readFile(
		path.join(STAGE_DIRECTORY, SUPERSEDED_ROOT, 'index.html'),
		'utf8',
	);
	const isFontHost = (href: string): boolean => href.includes('fonts.googleapis.com');
	const emittedFontLinks = linkHrefs(emittedIndex).filter(isFontHost);
	const sourceFontLinks = linkHrefs(sourceIndex).filter(isFontHost);

	/** The worker chunks, named by the emitted files rather than by expectation. */
	const workerChunks = first
		.filter((entry) => /^(?:lz|reminder)\./.test(entry.path))
		.map((entry) => entry.path);
	const runtimeChunk = first.find((entry) => entry.path.startsWith('runtime.'));
	const runtimeSource =
		runtimeChunk === undefined
			? ''
			: await readFile(path.join(STAGE_DIRECTORY, CANONICAL_ROOT, runtimeChunk.path), 'utf8');
	const manifest = JSON.parse(
		await readFile(path.join(STAGE_DIRECTORY, CANONICAL_ROOT, 'ngsw.json'), 'utf8'),
	) as Readonly<{ hashTable: Readonly<Record<string, string>> }>;
	const precached = workerChunks.filter(
		(file) => file.endsWith('.js') && `/${file}` in manifest.hashTable,
	);
	const referencedByRuntime = workerChunks.filter(
		(file) => file.endsWith('.js') && runtimeSource.includes(file.split('.')[1] ?? file),
	);

	/** The one chunk whose content hash moved against the superseded lane, read. */
	const movedChunk = changedAgainstSuperseded.find((name) => name.startsWith('main.'));
	const supersededMain = superseded.find((entry) => entry.path.startsWith('main.'));
	const currentMain = first.find((entry) => entry.path.startsWith('main.'));
	const sassReading =
