/**
 * The record of the offline-faithful rebuild: the migrated super-productivity
 * lane with the Angular 16 font inliner turned off.
 *
 * u21 read `app/dist/index.html` — the document u18j published — and found
 * forty-five `@font-face` rules that exist in no input, which is the body of the
 * Roboto stylesheet the builder fetched from `fonts.googleapis.com` while the
 * build was running. u21 established that from the document alone and said so:
 * it observed no build and captured no traffic. This round observes the build.
 *
 * Every number here is read at the moment the record is written: three build
 * logs, three egress logs, three emitted inventories — the two this round
 * produced and the superseded one, which is still on disk — the source and
 * emitted documents, the emitted runtime chunk and the emitted service-worker
 * manifest. The control build is part of the evidence rather than a rehearsal:
 * it is the same workspace u18j built, run under the same guard, and it goes red
 * on the fetch. A green control would have meant the guard was measuring
 * nothing.
 *
 * No witness work is done here and none is claimed. The deliverable is the
 * corrected lane and the record of it; the browser proof for this vertical
 * resumes against these bytes.
 */

import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { charNotIn, createRegExp, exactly, global as globalFlag, oneOrMore } from 'magic-regexp';
import * as path from 'pathe';
import { canonical, sha256 } from './angular-factoriolab-migration-run.ts';
import {
	emissionPointOf,
	inventoryOf,
	sealRecord,
	verifySealedRecord,
	type DistEntry,
	type SealedRecord,
} from './angular-factoriolab-build-lanes-run.ts';
import { CONSENT, EVIDENCE_DIRECTORY } from './angular-super-productivity-lanes-run.ts';
import { APPLIED_TREE, STAGE_DIRECTORY } from './angular-super-productivity-apply-run.ts';
import {
	CANONICAL_ROOT,
	REPEATED_ROOT,
	UNIT,
	type FontRound,
} from './angular-super-productivity-u23-font-run.ts';

export const FONT_LANE_FILE = 'u23-offline-font-lane.json';
/** The output root u18j published, kept on disk and read here as the superseded lane. */
export const SUPERSEDED_ROOT = 'app/dist';
/** The record this round supersedes, and the u21 reading it answers. */
export const SUPERSEDED_RECORD = 'u18j-worker-chunks-parity.json';
export const LOCALITY_FINDING = Object.freeze({
	record: 'evidence/runs/angular-super-productivity-v2-13-15/u21-font-inline-locality.json',
	digest: '7f7dbf94127e57ca79029a6c93a74ffd61f2ec1347e4ce3bf25b55bdbee5ff2a',
});

const LINK_HREF = createRegExp(
	exactly('<link')
		.and(oneOrMore(charNotIn('>')))
		.and('href="')
		.and(oneOrMore(charNotIn('"')).groupedAs('href'))
		.and('"'),
	[globalFlag],
);

/** Every `<link>` href in a document, in document order. */
export function linkHrefs(html: string): readonly string[] {
	return Object.freeze(
		[...html.matchAll(LINK_HREF)].map((match) => match.groups['href'] as string),
	);
